const header=document.querySelector('#header');
addEventListener('scroll',()=>header?.classList.toggle('scrolled',scrollY>24),{passive:true});
const drawer=document.querySelector('.mobile-drawer'),menu=document.querySelector('.menu-button');
function setMenu(open){drawer?.classList.toggle('open',open);drawer?.setAttribute('aria-hidden',String(!open));menu?.setAttribute('aria-expanded',String(open));document.body.style.overflow=open?'hidden':''}
menu?.addEventListener('click',()=>setMenu(true));document.querySelector('.drawer-close')?.addEventListener('click',()=>setMenu(false));drawer?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
const filters=[...document.querySelectorAll('.filters button')],items=[...document.querySelectorAll('.gallery-item')];
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.classList.remove('active'));button.classList.add('active');items.forEach(item=>item.classList.toggle('hidden',button.dataset.filter!=='all'&&!item.dataset.category.includes(button.dataset.filter)))}));
const lightbox=document.querySelector('#lightbox');items.forEach(item=>item.addEventListener('click',()=>{const image=lightbox.querySelector('img');image.src=item.dataset.image;image.alt=item.querySelector('img').alt;lightbox.showModal()}));lightbox?.querySelector('button')?.addEventListener('click',()=>lightbox.close());lightbox?.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
let requestText='';const form=document.querySelector('#quote-form');
form?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const files=[...form.querySelector('[type=file]').files].map(f=>f.name).join(', ')||'None selected';requestText=`SMARTVIEW ALUMINIUMS — QUOTE REQUEST\n\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nEmail: ${d.get('email')||'Not provided'}\nLocation: ${d.get('location')||'Not provided'}\nService: ${d.get('need')}\nMeasurements: ${d.get('sizes')||'Not provided'}\nQuantity: ${d.get('quantity')}\nFiles noted: ${files}\n\nProject notes:\n${d.get('message')||'None'}`;const result=document.querySelector('#form-result');result.hidden=false;result.scrollIntoView({behavior:'smooth',block:'nearest'})});
document.querySelector('#copy-request')?.addEventListener('click',async e=>{await navigator.clipboard.writeText(requestText);e.currentTarget.textContent='Copied';setTimeout(()=>e.currentTarget.textContent='Copy request',1500)});
document.querySelector('#download-request')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([requestText],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='smartview-quote-request.txt';a.click();URL.revokeObjectURL(url)});
